SELECT 


ORDER BY ${sortColumn} ${sortDirection}, c.correct_seq DESC

    LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE tb_inbound_correct SET correct_status = #{toStatus},
decided_by = #{decidedBy}, decided_at = CURRENT_TIMESTAMP, decide_remark = #{decideRemark},
updated_by = COALESCE(#{decidedBy}, updated_by), updated_at = CURRENT_TIMESTAMP WHERE correct_seq = #{correctSeq} AND correct_status = #{fromStatus}

UPDATE tb_inbound_correct_line
   SET applied_history_seq = #{historySeq}
 WHERE line_seq = #{lineSeq}
